struct StaticTask {
  int node, x, y, z;
}; // one entry of an SM's list: the graph node and the task's grid position
// a node: its grid, its first counter (-1: none) and its output buffer slot
// (-1: none); as an input's producer also its params (v, then a 0)
template <int X, int Y, int Z, int C = -1, int B = -1, int... P>
struct StaticNode {
  static constexpr int x = X, y = Y, z = Z, counter = C, buf = B;
  static constexpr int v[sizeof...(P) + 1] = {P..., 0};
};
template <int... P>
struct StaticParams {
  static constexpr int v[sizeof...(P) + 1] = {P..., 0};
}; // a node's params
template <int... S>
struct StaticBufSlots {
  static constexpr int v[sizeof...(S) + 1] = {S..., -1};
}; // a node's buffer slots (G::buf)
template <int... S>
struct StaticMapSlots {
  static constexpr int v[sizeof...(S) + 1] = {S..., -1};
}; // a node's map slots (Maps::m)

// what the host code sees of one GPU / of all GPUs
struct StaticGpuView {
  int gpu; // CUDA device index
  std::map<std::string, void *>
      tensors; // the graph's tensors on this GPU, by name
};
struct StaticContext {
  int num_gpus = 0, num_lists = 0;
  std::vector<StaticGpuView> gpus;
};
