// ---- the kernel ----
__global__ void __launch_bounds__(256, 1)
    layer_kernel(const __grid_constant__ static_mk::Maps maps,
                 static_mk::G g,
                 StaticTask const *static_tasks) {
  static_mk::KernelLocals L;
  static_mk::kernel_begin(g, L);
  StaticTask const *my =
      static_tasks + blockIdx.x * (static_mk::MAX_TASKS_PER_SM);
  bool warm_27 = false; // a task of node 27 ran on this SM: its code is in the
                        // instruction cache
  for (int ti = 0; ti < static_mk::MAX_TASKS_PER_SM; ti++) {
    StaticTask const tk = my[ti];
    if (tk.node < 0) {
      break;
    }
    switch (tk.node) {
      case 26:
        static_mk::run_gemm_tile<StaticNode<7, 14, 1, -1, 0>,
                                 StaticParams<0, 7168, 896, 0>,
                                 StaticBufSlots<>,
                                 StaticMapSlots<0, 2>,
                                 StaticNode<0, 0, 0>,
                                 StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 27:
        static_mk::run_topk_route<StaticNode<8, 1, 1, -1, 2>,
                                  StaticParams<896, 16>,
                                  StaticBufSlots<1>,
                                  StaticMapSlots<>,
                                  StaticNode<7, 14, 1, -1, 0, 0, 7168, 896, 0>,
                                  StaticNode<0, 0, 0>>(maps, g, L, tk, warm_27);
        warm_27 = true;
        break;
      case 28:
        static_mk::run_gemm_tile<StaticNode<28, 8, 1, -1, 3>,
                                 StaticParams<0, 7168, 3584, 0>,
                                 StaticBufSlots<>,
                                 StaticMapSlots<3, 2>,
                                 StaticNode<0, 0, 0>,
                                 StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 29:
        static_mk::run_sum_quant_send<
            StaticNode<28, 1, 1, -1, 4>,
            StaticParams<3584>,
            StaticBufSlots<>,
            StaticMapSlots<>,
            StaticNode<28, 8, 1, -1, 3, 0, 7168, 3584, 0>>(maps, g, L, tk);
        break;
      case 30:
        static_mk::run_gemm_tile<StaticNode<12, 8, 1, 0, 5>,
                                 StaticParams<1, 7168, 1536, 0>,
                                 StaticBufSlots<>,
                                 StaticMapSlots<5, 2>,
                                 StaticNode<0, 0, 0>,
                                 StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 31:
        static_mk::run_situ_and_mul<
            StaticNode<12, 1, 1, 32, 6>,
            StaticParams<>,
            StaticBufSlots<>,
            StaticMapSlots<>,
            StaticNode<12, 8, 1, 0, 5, 1, 7168, 1536, 0>>(maps, g, L, tk);
        break;
      case 34:
        static_mk::run_gemm_tile<StaticNode<56, 1, 1, 64, 7>,
                                 StaticParams<2, 768, 7168, 0>,
                                 StaticBufSlots<>,
                                 StaticMapSlots<7, 9>,
                                 StaticNode<12, 1, 1, 32, 6>,
                                 StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 35:
        static_mk::run_allreduce_send<
            StaticNode<56, 1, 1, -1, 8>,
            StaticParams<7168, 1>,
            StaticBufSlots<-1>,
            StaticMapSlots<>,
            StaticNode<56, 1, 1, 64, 7, 2, 768, 7168, 0>>(maps, g, L, tk);
        break;
      case 36:
        static_mk::run_moe_experts<
            StaticNode<148, 1, 1, 96, 11>,
            StaticParams<384>,
            StaticBufSlots<9, 10>,
            StaticMapSlots<10, 11, 12, 13, 14, 15, 16, 17, 18, 20, 22, 24, 25>,
            StaticNode<28, 1, 1, -1, 4, 3584>,
            StaticNode<8, 1, 1, -1, 2, 896, 16>,
            StaticNode<0, 0, 0>,
            StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 37:
        static_mk::run_allreduce_send<StaticNode<148, 1, 1, -1, 12>,
                                      StaticParams<3584, 16>,
                                      StaticBufSlots<4>,
                                      StaticMapSlots<>,
                                      StaticNode<148, 1, 1, 96, 11, 384>>(
            maps, g, L, tk);
        break;
      case 38:
        static_mk::run_sum_rmsnorm<StaticNode<2, 8, 1, -1, 15>,
                                   StaticParams<2, 925353388>,
                                   StaticBufSlots<13, 14>,
                                   StaticMapSlots<>,
                                   StaticNode<148, 1, 1, -1, 12, 3584, 16>,
                                   StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 39:
        static_mk::run_sum_gpus<StaticNode<8, 8, 1, -1, 16>,
                                StaticParams<>,
                                StaticBufSlots<>,
                                StaticMapSlots<>,
                                StaticNode<56, 1, 1, -1, 8, 7168, 1>>(
            maps, g, L, tk);
        break;
      case 40:
        static_mk::run_gemm_tile<StaticNode<56, 7, 1, -1, 17>,
                                 StaticParams<0, 3584, 7168, 1>,
                                 StaticBufSlots<>,
                                 StaticMapSlots<26, -1>,
                                 StaticNode<2, 8, 1, -1, 15, 2, 925353388>,
                                 StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 41:
        static_mk::run_sum_send<StaticNode<56, 14, 1, -1, 18>,
                                StaticParams<>,
                                StaticBufSlots<>,
                                StaticMapSlots<>,
                                StaticNode<56, 7, 1, -1, 17, 0, 3584, 7168, 1>>(
            maps, g, L, tk);
        break;
      case 42:
        static_mk::run_residual_add<StaticNode<148, 1, 1, -1, -1>,
                                    StaticParams<7168>,
                                    StaticBufSlots<19, 20>,
                                    StaticMapSlots<>,
                                    StaticNode<8, 8, 1, -1, 16>,
                                    StaticNode<56, 14, 1, -1, 18>,
                                    StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
    }
  }
  static_mk::kernel_end(g, L);
}

