#define ST_CK(x)                                                               \
  do {                                                                         \
    cudaError_t e_ = (x);                                                      \
    if (e_ != cudaSuccess) {                                                   \
      fprintf(stderr,                                                          \
              "layer: %s @%d: %s\n",                                           \
              #x,                                                              \
              __LINE__,                                                        \
              cudaGetErrorString(e_));                                         \
      exit(1);                                                                 \
    }                                                                          \
  } while (0)
static StaticTask const *const static_tasks_of[static_mk::GPUS] = {
    static_tasks_gpu0,
    static_tasks_gpu1,
    static_tasks_gpu2,
    static_tasks_gpu3,
    static_tasks_gpu4,
    static_tasks_gpu5,
    static_tasks_gpu6,
    static_tasks_gpu7};
